function system_issue_brief_plain_text(array $issue,array $briefRow,array $attachments=[]): string {
    $brief=json_decode((string)($briefRow['ai_brief_json']??'{}'),true)?:[];$recommendations=json_decode((string)($briefRow['owner_recommendations_json']??'[]'),true)?:[];$value=fn(string $key,string $fallback='—')=>system_issue_redact_copy_text(is_array($brief[$key]??null)?implode("\n",$brief[$key]):trim((string)($brief[$key]??$fallback)));$ownerText=$recommendations?implode("\n\n",array_map(fn($r)=>system_issue_redact_copy_text((string)($r['text']??'')),$recommendations)):'—';$route=preg_replace('/\?.*$/','',(string)($issue['route']??''));$evidence=$attachments?"\nEvidence files: ".implode(', ',array_map(fn($a)=>basename((string)$a['original_name']),$attachments)):'';
    return "SYSTEM ISSUE REPAIR BRIEF\n\nIssue ID: ".($issue['issue_key']??'')."\nBrief version: ".(int)($briefRow['version_number']??1)."\nGenerated: ".($briefRow['created_at']??'')."\nCurrent status: ".system_issue_status_label((string)($issue['employee_status']??'reported'))."\nRisk level: ".strtoupper((string)($briefRow['ai_risk_level']??$issue['ai_risk_level']??'unknown'))."\n\nTITLE\n".$value('title',(string)($issue['title']??''))."\n\nSUMMARY\n".$value('summary')."\n\nEMPLOYEE REPORT\nWhat is the problem: ".system_issue_redact_copy_text((string)($issue['problem']??''))."\nWhere did it happen: ".system_issue_redact_copy_text((string)($issue['location']??''))."\nWhat was the employee trying to do: ".system_issue_redact_copy_text((string)($issue['attempted_action']??''))."\nWhat went wrong: ".system_issue_redact_copy_text((string)($issue['observed_behaviour']??''))."\nWhat should have happened: ".system_issue_redact_copy_text((string)($issue['expected_behaviour']??'')).$evidence."\n\nOWNER RECOMMENDATIONS\n".$ownerText."\n\nOBSERVED BEHAVIOUR\n".$value('observed_behaviour')."\n\nEXPECTED BEHAVIOUR\n".$value('expected_behaviour')."\n\nSTEPS TO REPRODUCE\n".$value('steps_to_reproduce')."\n\nAFFECTED MODULES AND ROUTES\n".$value('affected_module').($route?"\n".system_issue_redact_copy_text($route):'')."\n\nLIKELY ROOT CAUSE\n".$value('likely_root_cause')."\n\nAPPROVED SCOPE OF FIX\n".$value('scope_of_fix')."\n\nDO NOT CHANGE\n".$value('do_not_change')."\n\nACCEPTANCE CRITERIA\n".$value('acceptance_criteria')."\n\nREQUIRED TESTS\n".$value('required_tests')."\n\nDEPLOYMENT AND LIVE VERIFICATION REQUIREMENTS\n".$value('deployment_and_live_verification_requirements',$value('deployment_notes'))."\n\nMISSING INFORMATION OR UNCERTAINTIES\n".$value('missing_information');
}
function system_issue_uploads(int $issueId,int $employeeId,?int $requestId=null): void {
    if(empty($_FILES['evidence']['name'])||!is_array($_FILES['evidence']['name']))return;$dir=BASE_PATH.'/storage/system-issues';if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('Evidence storage is unavailable.');$finfo=new finfo(FILEINFO_MIME_TYPE);
    foreach($_FILES['evidence']['name']as$i=>$original){$error=(int)($_FILES['evidence']['error'][$i]??UPLOAD_ERR_NO_FILE);if($error===UPLOAD_ERR_NO_FILE)continue;if($error!==UPLOAD_ERR_OK)throw new RuntimeException('One evidence file could not be uploaded.');$tmp=(string)$_FILES['evidence']['tmp_name'][$i];$size=(int)$_FILES['evidence']['size'][$i];$mime=(string)$finfo->file($tmp);if(!isset(SYSTEM_ISSUE_ALLOWED_MIME[$mime])||$size>25*1024*1024)throw new RuntimeException('Evidence must be PNG, JPG, WEBP, MP4 or PDF and no larger than 25 MB.');$stored=bin2hex(random_bytes(18)).'.'.SYSTEM_ISSUE_ALLOWED_MIME[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$stored))throw new RuntimeException('Evidence could not be stored.');db()->prepare('INSERT INTO system_issue_attachments(issue_id,information_request_id,uploaded_by,original_name,stored_name,mime_type,size_bytes,sha256) VALUES(?,?,?,?,?,?,?,?)')->execute([$issueId,$requestId,$employeeId,mb_substr(basename((string)$original),0,255),$stored,$mime,$size,hash_file('sha256',$dir.'/'.$stored)]);}
}
